function Page_CommonActViewBase.CreatePageActView(actId,parentPref)
    ---@type act_bussiness_config_cell
    local actConfig = CommonHelper:GetTableDataByID(ConfigNames.act_bussiness_config, actId)
    local pageActView
    if actConfig==nil  then
        logError("该活动id没有对应的PageActView",actId)
    elseif actConfig.actstyle == CommonFestivalType.ActLuckRotaryTable then
        pageActView = Page_CommonActLuckRotaryTableView()
    elseif actConfig.actstyle == CommonFestivalType.SpringSignIn then
        pageActView = Page_CommonActSignInView()
    elseif actConfig.actstyle == CommonFestivalType.LuckInfo then
        pageActView = Page_CommonActLuckInfoView()
    elseif actConfig.actstyle ==  CommonFestivalType.ActWordList then
        pageActView = Page_CommonActCollectWordsView()
    elseif actConfig.actstyle ==  CommonFestivalType.DualOutput then
        pageActView = Page_CommonFestivalDualOutputView()
    elseif actConfig.actstyle ==  CommonFestivalType.TimeToken then
        pageActView = Page_CommonActTimeTokenView()
    elseif actConfig.actstyle ==  CommonFestivalType.ReBackSupport then
        pageActView = Page_CommonActSupportView()
    elseif actConfig.actstyle ==  CommonFestivalType.RechargeReward then
        pageActView = Page_CommonActRechargeRewardView()
    elseif actConfig.actstyle ==  CommonFestivalType.GiftPackage then
        pageActView = Page_CommonActRotaryTableBagView()
    end
    if pageActView then
        Page_CommonActViewBase.initialize(pageActView,actId,parentPref)
        pageActView:OnAwake()
    end
    return pageActView
end

function Page_CommonActViewBase:initialize(actId,parentPref)
    if self and actId and parentPref  then
        self.parentPref=parentPref
        ---@type act_bussiness_config_cell
        self.actConfig = CommonHelper:GetTableDataByID(ConfigNames.act_bussiness_config, actId)
        self.canvasGroup = UIUtil.GetTypeChildWightByParent(self:GetPageName(), self.parentPref, typeof(CanvasGroup))
        self.gameObject = self.canvasGroup.gameObject
        self:SetCanvasGroup(false)
        self.IsOpen=false
    else
        logWarn("该继承未初始化基类")
    end
end

function Page_CommonActViewBase:Open()
    CommonHelper:GetComponentSetUITexture("pagebg", self.parentPref, self.actConfig.actbg .. ".png", self:GetUIModuleID())
    self:SetCanvasGroup(true)
    self.IsOpen=true
    self:OnOpen()
end

function Page_CommonActViewBase:Close()
    self.IsOpen=false
    self:SetCanvasGroup(false)
    self:OnClose()
end

function Page_CommonActViewBase:SetCanvasGroup(active)
    UIUtil.ShowCanvasGroup(self.canvasGroup,active)
end

