function Page_CommonActViewBase:GetDataTimeString()
    local bTime, eTime = CommonFestivalDataManager:Get():GetActTime(self.actConfig.C_ID)
    local _beginTime = CommonHelper:ConvertIntToDataTime(bTime * 1000)
    local _endTime = CommonHelper:ConvertIntToDataTime(eTime * 1000)
    local durationTime = string.format(CommonHelper:GetTempStr_Default(TemplateStringID.FestivalTimeText,
            _beginTime.Month, _beginTime.Day, _beginTime.Hour, _beginTime.Minute,
            _endTime.Month, _endTime.Day, _endTime.Hour, _endTime.Minute))
    return durationTime
end

